<template>
  <AppLayout>
    <div class="min-w-0 space-y-5">
      <header class="flex flex-wrap items-center justify-between gap-3"><h1 class="text-2xl font-semibold">{{ t('providerHub.operations') }}</h1><div class="flex gap-2"><RouterLink class="btn btn-secondary" to="/admin/providers"><Icon name="cog" size="sm" />{{ t('providerHub.providersLink') }}</RouterLink><button class="btn btn-secondary" :disabled="loading" :title="t('providerHub.refresh')" :aria-label="t('providerHub.refresh')" @click="load"><Icon name="refresh" size="sm" /></button></div></header>
      <form class="space-y-3 border-y border-gray-200 py-4 dark:border-dark-700" @submit.prevent="page = 1; load()">
        <div class="flex flex-wrap gap-2"><button v-for="preset in presets" :key="preset" type="button" class="btn btn-secondary" :disabled="loading" @click="setPeriod(preset)">{{ t(`providerHub.${preset}`) }}</button></div>
        <div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
          <label class="field">{{ t('providerHub.from') }}<input v-model="from" type="datetime-local" class="input" required /></label><label class="field">{{ t('providerHub.until') }}<input v-model="until" type="datetime-local" class="input" required /></label>
          <label class="field">{{ t('providerHub.supplier') }}<select v-model.number="supplierId" class="input" @change="walletId = 0"><option :value="0">{{ t('providerHub.all') }}</option><option v-for="s in hub?.suppliers" :key="s.id" :value="s.id">{{ s.name }}</option></select></label><label class="field">{{ t('providerHub.wallet') }}<select v-model.number="walletId" class="input"><option :value="0">{{ t('providerHub.all') }}</option><option v-for="w in walletChoices" :key="w.id" :value="w.id">{{ w.name }}</option></select></label>
          <label class="field">{{ t('providerHub.account') }} ID<input v-model.number="accountId" class="input" type="number" min="0" step="1" /></label><label class="field">{{ t('providerHub.group') }} ID<input v-model.number="groupId" class="input" type="number" min="0" step="1" /></label><label class="field">{{ t('providerHub.model') }}<input v-model="model" class="input" maxlength="160" /></label><label class="field">{{ t('providerHub.dimension') }}<select v-model="dimension" class="input"><option v-for="d in dimensions" :key="d" :value="d">{{ t(`providerHub.${d}`) }}</option></select></label>
        </div><button class="btn btn-primary" :disabled="loading" type="submit"><Icon name="search" size="sm" />{{ t('providerHub.apply') }}</button>
      </form>
      <p v-if="error" role="alert" class="text-sm text-red-600">{{ error }}</p><p v-if="loading" role="status" class="text-sm text-gray-500">{{ t('providerHub.loading') }}</p>
      <template v-if="snapshot">
        <div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-6">
          <div v-for="metric in metrics" :key="metric.label" class="min-w-0 rounded-lg border border-gray-200 p-4 dark:border-dark-700"><div class="text-xs leading-5 text-gray-500">{{ t(`providerHub.${metric.label}`) }}</div><div class="mt-2 break-words text-xl font-semibold tabular-nums" :class="metric.negative ? 'text-red-600' : ''">{{ metric.value }}</div></div>
        </div>
        <p class="text-xs leading-5 text-gray-500">{{ t('providerHub.costNote') }} {{ t('providerHub.profitCoverage', { known: snapshot.summary.comparable_count, total: snapshot.summary.requests }) }}<br />{{ t('providerHub.activation', { time: date(snapshot.started_at) }) }}</p>
        <section class="border-y border-gray-200 py-4 dark:border-dark-700"><h2 class="mb-4 font-semibold">{{ t('providerHub.trend') }}</h2><div class="h-64 w-full"><Line v-if="snapshot.trend.length" :data="chartData" :options="chartOptions" /><p v-else class="py-10 text-center text-sm text-gray-500">{{ t('providerHub.empty') }}</p></div></section>
        <section class="space-y-3"><h2 class="font-semibold">{{ t('providerHub.breakdown') }}</h2><div class="table-scroll"><table class="ops-table"><thead><tr><th>{{ t(`providerHub.${appliedDimension}`) }}</th><th>{{ t('providerHub.requests') }}</th><th>{{ t('providerHub.revenue') }} USD</th><th>{{ t('providerHub.cost') }} USD</th><th>{{ t('providerHub.profit') }} USD</th><th>{{ t('providerHub.coverage') }}</th></tr></thead><tbody><tr v-for="row in snapshot.breakdown" :key="row.key"><td><button class="max-w-80 break-all text-left text-primary-600 hover:underline dark:text-primary-300" @click="drill(row.key)">{{ breakdownName(row.key, row.name) }}</button></td><td>{{ number(row.metrics.requests) }}</td><td>{{ number(row.metrics.request_valuation) }}</td><td>{{ row.metrics.usd_priced ? number(row.metrics.usd_cost) : t('providerHub.unknown') }}</td><td :class="row.metrics.comparable_profit < 0 ? 'text-red-600' : ''">{{ row.metrics.comparable_count ? number(row.metrics.comparable_profit) : t('providerHub.unknown') }}</td><td>{{ coverage(row.metrics) }}</td></tr><tr v-if="!snapshot.breakdown.length"><td colspan="6">{{ t('providerHub.empty') }}</td></tr></tbody></table></div><p v-if="snapshot.breakdown.length >= snapshot.breakdown_limit" class="text-xs text-gray-500">{{ t('providerHub.groupingLimit', { count: snapshot.breakdown_limit }) }}</p></section>
        <section class="space-y-3"><h2 class="font-semibold">{{ t('providerHub.receipts') }}</h2><div class="table-scroll"><table class="ops-table"><thead><tr><th>{{ t('providerHub.time') }}</th><th>{{ t('providerHub.account') }}</th><th>{{ t('providerHub.model') }}</th><th>{{ t('providerHub.revenue') }} USD</th><th>{{ t('providerHub.cost') }}</th><th>{{ t('providerHub.evidence') }}</th><th>{{ t('providerHub.actions') }}</th></tr></thead><tbody><tr v-for="r in snapshot.receipts" :key="`${r.api_key_id}:${r.request_key}`"><td class="whitespace-nowrap text-xs">{{ date(r.observed_at) }}</td><td class="max-w-48 break-words">{{ accountName(r.account_id) }}<div class="text-xs text-gray-500">{{ r.wallet_name || t('providerHub.unknown') }}</div></td><td class="max-w-64 break-all">{{ r.model }}</td><td>{{ amount(r.request_valuation) }}</td><td>{{ amount(r.effective_cost, r.effective_currency || '') }}</td><td><span class="inline-flex rounded px-2 py-1 text-xs" :class="evidenceClass(r.evidence)">{{ t(`providerHub.${r.evidence}`) }}</span></td><td><button class="icon-button" :title="t('providerHub.details')" :aria-label="t('providerHub.details')" @click="openReceipt(r)"><Icon name="eye" size="sm" /></button></td></tr><tr v-if="!snapshot.receipts.length"><td colspan="7">{{ t('providerHub.empty') }}</td></tr></tbody></table></div><div class="flex items-center justify-between gap-3 text-sm"><span>{{ t('providerHub.page') }} {{ page }} · {{ t('providerHub.requests') }} {{ number(snapshot.summary.requests) }}</span><div class="flex gap-2"><button class="btn btn-secondary" :disabled="loading || page <= 1" @click="page--; load()">{{ t('providerHub.previous') }}</button><button class="btn btn-secondary" :disabled="loading || page * 20 >= snapshot.summary.requests" @click="page++; load()">{{ t('providerHub.next') }}</button></div></div></section>
        <div class="grid gap-6 xl:grid-cols-2">
          <section class="min-w-0 space-y-3"><h2 class="font-semibold">{{ t('providerHub.cashOverview') }}</h2><p class="text-sm text-gray-500">{{ t('providerHub.clientBalance') }}: {{ amount(snapshot.balances.positive, 'USD') }}</p><div class="table-scroll"><table class="ops-table"><thead><tr><th>{{ t('providerHub.currency') }}</th><th>{{ t('providerHub.cashReceived') }}</th><th>{{ t('providerHub.refundedCredits') }}</th></tr></thead><tbody><tr v-for="row in snapshot.cash" :key="`${row.currency}:${row.order_type}`"><td>{{ row.currency }}<div class="text-xs text-gray-500">{{ row.order_type }}</div></td><td>{{ number(row.received) }}</td><td>{{ number(row.refunded_credits) }} USD</td></tr><tr v-if="!snapshot.cash.length"><td colspan="3">{{ t('providerHub.empty') }}</td></tr></tbody></table></div></section>
          <section class="min-w-0 space-y-3"><h2 class="font-semibold">{{ t('providerHub.purchaseCash') }}</h2><div class="table-scroll"><table class="ops-table"><thead><tr><th>{{ t('providerHub.currency') }}</th><th>{{ t('providerHub.purchasePaid') }}</th><th>{{ t('providerHub.purchaseRefunded') }}</th></tr></thead><tbody><tr v-for="row in snapshot.purchases" :key="row.currency"><td>{{ row.currency }}</td><td>{{ number(row.paid || 0) }}</td><td>{{ number(row.refunded || 0) }}</td></tr><tr v-if="!snapshot.purchases.length"><td colspan="3">{{ t('providerHub.empty') }}</td></tr></tbody></table></div><div class="flex flex-wrap gap-x-5 gap-y-2 text-xs text-gray-500"><span v-for="row in snapshot.monitoring" :key="row.source">{{ t('providerHub.monitorCost') }} · {{ row.source }}: {{ number(row.recorded_cost) }} USD</span></div></section>
        </div>
      </template>
    </div>
    <BaseDialog :show="Boolean(receipt)" :title="t('providerHub.receipt')" width="wide" :close-on-click-outside="!saving" :close-on-escape="!saving" @close="closeReceipt">
      <div v-if="receipt" class="space-y-5">
        <dl class="grid grid-cols-[minmax(80px,130px)_minmax(0,1fr)] gap-x-4 gap-y-3 text-sm"><dt class="text-gray-500">{{ t('providerHub.account') }}</dt><dd>{{ accountName(receipt.account_id) }}</dd><dt class="text-gray-500">{{ t('providerHub.supplier') }}</dt><dd>{{ receipt.supplier_name || t('providerHub.unknown') }} / {{ receipt.wallet_name || t('providerHub.unknown') }}</dd><dt class="text-gray-500">{{ t('providerHub.upstreamRequest') }}</dt><dd class="break-all font-mono text-xs">{{ receipt.upstream_request_id || '—' }}</dd><dt class="text-gray-500">{{ t('providerHub.model') }}</dt><dd class="break-all">{{ receipt.upstream_model }}</dd><dt class="text-gray-500">{{ t('providerHub.originalCost') }}</dt><dd>{{ amount(receipt.estimated_cost, receipt.cost_currency || '') }}</dd><dt class="text-gray-500">{{ t('providerHub.cost') }}</dt><dd>{{ amount(receipt.effective_cost, receipt.effective_currency || '') }} · {{ t(`providerHub.${receipt.evidence}`) }}</dd><dt class="text-gray-500">{{ t('providerHub.reference') }}</dt><dd class="break-all">{{ receipt.invoice_reference || '—' }}</dd><dt class="text-gray-500">{{ t('providerHub.ruleVersion') }}</dt><dd>#{{ receipt.rule_id || '—' }}</dd></dl>
        <details class="border-y border-gray-200 py-3 dark:border-dark-700"><summary class="cursor-pointer text-sm font-medium">{{ t('providerHub.snapshot') }}</summary><pre class="mt-3 max-h-56 overflow-auto whitespace-pre-wrap break-all text-xs">{{ JSON.stringify({ rule: receipt.rule_snapshot, credit_cost: receipt.credit_cost, measurements: receipt.measurements }, null, 2) }}</pre></details>
        <form id="procurement-reconcile" class="space-y-3" @submit.prevent="reconcile"><h3 class="font-semibold">{{ t('providerHub.reconcile') }}</h3><p v-if="receiptError" role="alert" class="text-sm text-red-600">{{ receiptError }}</p><fieldset :disabled="saving" class="grid gap-3 sm:grid-cols-2"><label class="field">{{ t('providerHub.amount') }}<input v-model.number="adjustment.amount" type="number" min="0" step="any" class="input" required /></label><label class="field">{{ t('providerHub.currency') }}<input v-model="adjustment.currency" class="input" maxlength="3" pattern="[A-Za-z]{3}" required /></label><label class="field">{{ t('providerHub.fxToUsd') }}<input v-model="adjustment.fx_to_usd" type="number" min="0.000000000001" step="any" class="input" :disabled="adjustment.currency.toUpperCase() === 'USD'" /></label><label class="field">{{ t('providerHub.reference') }}<input v-model="adjustment.reference" class="input" required maxlength="256" /></label><label class="field sm:col-span-2">{{ t('providerHub.note') }}<textarea v-model="adjustment.note" class="input" rows="2" maxlength="2000" /></label></fieldset></form>
      </div><template #footer><div class="flex justify-end gap-2"><button class="btn btn-secondary" :disabled="saving" @click="closeReceipt">{{ t('providerHub.close') }}</button><button form="procurement-reconcile" type="submit" class="btn btn-primary" :disabled="saving"><Icon name="check" size="sm" />{{ t('providerHub.save') }}</button></div></template>
    </BaseDialog>
  </AppLayout>
</template>

<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { useI18n } from 'vue-i18n'
import { Line } from 'vue-chartjs'
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Tooltip, Legend, type ChartOptions } from 'chart.js'
import AppLayout from '@/components/layout/AppLayout.vue'
import BaseDialog from '@/components/common/BaseDialog.vue'
import Icon from '@/components/icons/Icon.vue'
import { getProviderHub, getProviderOperations, providerHubWrite, type ProviderHubState, type OperationsSnapshot, type OperationsMetrics, type ProcurementReceipt } from '@/api/admin/providerHub'
ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Tooltip, Legend)
const { t } = useI18n()
const hub = ref<ProviderHubState | null>(null), snapshot = ref<OperationsSnapshot | null>(null), error = ref(''), loading = ref(false), page = ref(1)
function localTime(d: Date) { return new Date(d.getTime() - d.getTimezoneOffset() * 60000).toISOString().slice(0, 16) }
const until = ref(localTime(new Date())), from = ref(localTime(new Date(Date.now() - 7 * 86400000))), supplierId = ref(0), walletId = ref(0), accountId = ref(0), groupId = ref(0), model = ref(''), dimension = ref('supplier'), appliedDimension = ref('supplier')
const dimensions = ['supplier', 'wallet', 'account', 'model', 'group'], presets = ['today', 'yesterday', 'sevenDays']
const walletChoices = computed(() => hub.value?.wallets.filter(w => !supplierId.value || w.supplier_id === supplierId.value) ?? [])
const receipt = ref<ProcurementReceipt | null>(null), receiptError = ref(''), saving = ref(false)
const adjustment = reactive({ amount: 0, currency: 'USD', fx_to_usd: '' as string | number, reference: '', note: '', operation_id: '' })
const metrics = computed(() => { const m = snapshot.value?.summary; return m ? [
  { label: 'requests', value: number(m.requests) }, { label: 'valuation', value: number(m.request_valuation) },
  { label: 'procurementCost', value: m.usd_priced ? number(m.usd_cost) : t('providerHub.unknown') },
  { label: 'comparableProfit', value: m.comparable_count ? number(m.comparable_profit) : t('providerHub.unknown'), negative: m.comparable_profit < 0 },
  { label: 'coverage', value: coverage(m) }, { label: 'missing', value: number(m.unknown) },
] : [] })
const chartData = computed(() => ({ labels: snapshot.value?.trend.map(p => p.day) ?? [], datasets: [
  { label: t('providerHub.revenue'), data: snapshot.value?.trend.map(p => p.metrics.request_valuation) ?? [], borderColor: '#0891b2', backgroundColor: '#0891b2', tension: 0.15, pointRadius: 2 },
  { label: t('providerHub.cost'), data: snapshot.value?.trend.map(p => p.metrics.usd_priced ? p.metrics.usd_cost : null) ?? [], borderColor: '#e11d48', backgroundColor: '#e11d48', tension: 0.15, pointRadius: 2 },
  { label: t('providerHub.profit'), data: snapshot.value?.trend.map(p => p.metrics.comparable_count ? p.metrics.comparable_profit : null) ?? [], borderColor: '#059669', backgroundColor: '#059669', tension: 0.15, pointRadius: 2 },
] }))
const chartOptions: ChartOptions<'line'> = { responsive: true, maintainAspectRatio: false, animation: false, plugins: { legend: { position: 'bottom' } }, scales: { y: { ticks: { maxTicksLimit: 6 } }, x: { ticks: { maxTicksLimit: 8 } } } }
let alive = true, sequence = 0, controller: AbortController | undefined
function number(value: number) { return Number(value).toLocaleString(undefined, { maximumFractionDigits: 6 }) }
function amount(value: number | null, currency = '') { return value == null ? t('providerHub.unknown') : `${number(value)} ${currency}` }
function date(value: string) { return new Date(value).toLocaleString() }
function coverage(m: OperationsMetrics) { return m.requests ? `${(m.usd_priced / m.requests * 100).toFixed(1)}%` : '—' }
function accountName(id: number) { const a = hub.value?.accounts.find(a => a.id === id); return a ? `${a.name} #${id}` : `#${id}` }
function evidenceClass(value: string) { return value === 'reconciled' ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300' : value === 'estimated' ? 'bg-cyan-50 text-cyan-700 dark:bg-cyan-950/40 dark:text-cyan-300' : 'bg-gray-100 text-gray-500 dark:bg-dark-800' }
function breakdownName(key: string, name: string) { if (key === '0' && ['supplier', 'wallet'].includes(appliedDimension.value)) return t('providerHub.unknown'); if (appliedDimension.value === 'account') return accountName(Number(key)); return name }
async function load() {
  const a = new Date(from.value), b = new Date(until.value)
  if (!Number.isFinite(a.getTime()) || !Number.isFinite(b.getTime()) || a >= b || b.getTime() - a.getTime() > 31 * 86400000) { error.value = t('providerHub.invalid'); return }
  const request = ++sequence; controller?.abort(); controller = new AbortController(); loading.value = true; error.value = ''; snapshot.value = null
  const selectedDimension = dimension.value
  try { const data = await getProviderOperations({ from: a.toISOString(), until: b.toISOString(), supplier_id: supplierId.value, wallet_id: walletId.value, account_id: accountId.value || 0, group_id: groupId.value || 0, model: model.value.trim(), dimension: selectedDimension, page: page.value, page_size: 20, timezone: Intl.DateTimeFormat().resolvedOptions().timeZone }, controller.signal); if (alive && request === sequence) { snapshot.value = data; appliedDimension.value = selectedDimension } }
  catch { if (alive && request === sequence) error.value = t('providerHub.failed') }
  finally { if (alive && request === sequence) loading.value = false }
}
function setPeriod(preset: string) { const now = new Date(), start = new Date(now); start.setHours(0, 0, 0, 0); let end = now; if (preset === 'yesterday') { end = new Date(start); start.setDate(start.getDate() - 1) } else if (preset === 'sevenDays') start.setDate(start.getDate() - 6); from.value = localTime(start); until.value = localTime(end); page.value = 1; void load() }
function drill(key: string) { if (key === '0' || loading.value) return; if (appliedDimension.value === 'supplier') { supplierId.value = Number(key); walletId.value = 0; dimension.value = 'wallet' } else if (appliedDimension.value === 'wallet') { walletId.value = Number(key); dimension.value = 'account' } else if (appliedDimension.value === 'account') { accountId.value = Number(key); dimension.value = 'model' } else if (appliedDimension.value === 'group') { groupId.value = Number(key); dimension.value = 'model' } else model.value = key; page.value = 1; void load() }
function openReceipt(value: ProcurementReceipt) { receipt.value = value; receiptError.value = ''; Object.assign(adjustment, { amount: value.effective_cost ?? 0, currency: value.effective_currency || 'USD', fx_to_usd: value.rule_snapshot.fx_to_usd ?? '', reference: value.invoice_reference || '', note: '', operation_id: crypto.randomUUID() }) }
function closeReceipt() { if (!saving.value) receipt.value = null }
async function reconcile() { if (!receipt.value || saving.value) return; saving.value = true; receiptError.value = ''; try { await providerHubWrite('/adjustments', { api_key_id: receipt.value.api_key_id, request_key: receipt.value.request_key, amount: adjustment.amount, currency: adjustment.currency, fx_to_usd: adjustment.fx_to_usd === '' ? null : Number(adjustment.fx_to_usd), reference: adjustment.reference, note: adjustment.note, operation_id: adjustment.operation_id }); if (alive) { receipt.value = null; await load() } } catch { if (alive) receiptError.value = t('providerHub.failed') } finally { if (alive) saving.value = false } }
onMounted(async () => { try { hub.value = await getProviderHub() } catch { error.value = t('providerHub.failed') } if (alive) await load() })
onUnmounted(() => { alive = false; sequence++; controller?.abort() })
</script>

<style scoped>
.field { @apply flex min-w-0 flex-col gap-1.5 text-sm; }
.icon-button { @apply inline-flex h-9 w-9 items-center justify-center rounded-md border border-gray-200 text-gray-500 hover:bg-gray-100 dark:border-dark-700 dark:hover:bg-dark-800; }
.table-scroll { @apply min-w-0 overflow-x-auto border-y border-gray-200 dark:border-dark-700; }
.ops-table { @apply w-full text-left text-sm tabular-nums; }
.ops-table:has(th:nth-child(5)) { min-width: 760px; }
.ops-table th { @apply whitespace-nowrap bg-gray-50 px-3 py-3 text-xs font-medium text-gray-500 dark:bg-dark-900; }
.ops-table td { @apply border-t border-gray-100 px-3 py-3 align-top dark:border-dark-700; }
</style>
